INSERT INTO private.worker_jobs SELECT md5('worker'||i)::uuid, CASE WHEN i%NULLIF(__ACTIVE_MODULO__,0)=0 THEN 'running' ELSE 'succeeded' END,jsonb_build_object('job_id',md5('job'||i)::uuid), '2026-08-01','2026-08-02','2026-08-01' FROM generate_series(1,__WORKER_ROWS__)i;
INSERT INTO private.lca_package_artifacts SELECT md5('artifact'||i)::uuid, CASE WHEN i%7=0 THEN NULL ELSE md5('worker'||i)::uuid END,md5('job'||i)::uuid,i%17=0,CASE WHEN i%3=0 THEN 'deleted' ELSE 'ready' END,CASE WHEN i%19=0 THEN NULL WHEN i%13=0 THEN '2026-11-01'::timestamptz ELSE '2026-08-01'::timestamptz END,100+i FROM generate_series(1,__ARTIFACT_ROWS__)i;
INSERT INTO private.lca_package_request_cache SELECT md5('cache'||i)::uuid, CASE WHEN i%7=0 THEN NULL ELSE md5('worker'||i)::uuid END,md5('job'||i)::uuid,CASE WHEN i%11=0 THEN 'pending' ELSE 'ready' END,CASE WHEN i%9=0 THEN '2026-10-01'::timestamptz ELSE '2026-08-01'::timestamptz END,CASE WHEN i%4=0 THEN md5('artifact'||i)::uuid ELSE NULL END,CASE WHEN i%3=0 THEN md5('artifact'||i)::uuid ELSE NULL END,i%20 FROM generate_series(1,__CACHE_ROWS__)i;
INSERT INTO private.lca_package_export_items SELECT md5('item'||i)::uuid, CASE WHEN i%7=0 THEN NULL ELSE md5('worker'||(i%4000+1))::uuid END,md5('job'||(i%4000+1))::uuid,CASE WHEN i%17=0 THEN '2026-10-01'::timestamptz ELSE '2026-08-01'::timestamptz END FROM generate_series(1,__EXPORT_ROWS__)i;
